CREATE TABLE `CLASS` (`CLASS_CODE` VARCHAR(100), `CRS_CODE` VARCHAR(100), `CLASS_SECTION` VARCHAR(100), `CLASS_TIME` VARCHAR(100), `CLASS_ROOM` VARCHAR(100), `PROF_NUM` DECIMAL(18,2));
CREATE TABLE `COURSE` (`CRS_CODE` VARCHAR(100), `DEPT_CODE` VARCHAR(100), `CRS_DESCRIPTION` VARCHAR(100), `CRS_CREDIT` DECIMAL(18,2));
CREATE TABLE `DEPARTMENT` (`DEPT_CODE` VARCHAR(100), `DEPT_NAME` VARCHAR(100), `SCHOOL_CODE` VARCHAR(100), `EMP_NUM` DECIMAL(18,2), `DEPT_ADDRESS` VARCHAR(100), `DEPT_EXTENSION` VARCHAR(100));
CREATE TABLE `EMPLOYEE` (`EMP_NUM` DECIMAL(18,2), `EMP_LNAME` VARCHAR(100), `EMP_FNAME` VARCHAR(100), `EMP_INITIAL` VARCHAR(100), `EMP_JOBCODE` VARCHAR(100), `EMP_HIREDATE` DATETIME, `EMP_DOB` DATETIME);
CREATE TABLE `ENROLL` (`CLASS_CODE` VARCHAR(100), `STU_NUM` DECIMAL(18,2), `ENROLL_GRADE` VARCHAR(100));
CREATE TABLE `PROFESSOR` (`EMP_NUM` DECIMAL(18,2), `DEPT_CODE` VARCHAR(100), `PROF_OFFICE` VARCHAR(100), `PROF_EXTENSION` VARCHAR(100), `PROF_HIGH_DEGREE` VARCHAR(100));
CREATE TABLE `STUDENT` (`STU_NUM` DECIMAL(18,2), `STU_LNAME` VARCHAR(100), `STU_FNAME` VARCHAR(100), `STU_INIT` VARCHAR(100), `STU_DOB` DATETIME, `STU_HRS` DECIMAL(18,2), `STU_CLASS` VARCHAR(100), `STU_GPA` DECIMAL(18,2), `STU_TRANSFER` DECIMAL(18,2), `DEPT_CODE` VARCHAR(100), `STU_PHONE` VARCHAR(100), `PROF_NUM` DECIMAL(18,2));
